double findMedian(double[] nums) {
  int n = nums.length;
  if (n % 2 == 1) return nums[n / 2];

  double leftSum = 0.0, rightSum = 0.0;
  for (int i = 0; i < n - 1; ++i) leftSum += nums[i] * (n - i);
  for (int j = 1; j < n; ++j) rightSum += nums[j] * j;

  while (true) {
    double mid = (leftSum + rightSum) / n;
    double leftCount = 0.0, rightCount = 0.0;

    for (double x : nums) {
      leftCount += (x <= mid) ? 1.0 : 0.0;
      rightCount += (x >= mid) ? 1.0 : 0.0;
    }

    if ((Math.abs(leftCount - rightCount) < 1e-9)) break;
    else if (rightCount > leftCount) leftSum -= mid * Math.min(n - leftCount, rightCount - leftCount), rightSum -= mid * Math.max(leftCount - rightCount, 0);
    else leftSum += mid * Math.min(rightCount - leftCount, 0), rightSum += mid * Math.min(leftCount - rightCount, 0);
  }

  return (leftSum + rightSum) / n;
}


