List<int> mergeSort(List<int> a, int low, int high) {
  if (low >= high) {
    return [a[low]];
  }

  int mid = (low + high) ~/ 2;
  List<int> left = mergeSort(a, low, mid);
  List<int> right = mergeSort(a, mid + 1, high);

  List<int> merged = [];
  int i = 0, j = 0;

  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      merged.add(left[i]);
      i++;
    } else {
      merged.add(right[j]);
      j++;
    }
