String compress(String text) {
  if (text.length <= 1) return text;

  final list = <String>[];
  int count = 0;

  for (int i = 0; i < text.length;) {
    String currentChar = text[i];
    count = 1;

    while (i + 1 < text.length && text[i + 1] == currentChar) {
      i++;
      count++;
    }

    list.add('${count}$currentChar');
    i++;
  }

  return list.join('');
}


