String _encrypt(String text, String key) {
  int n = text.length;
  List<String> result = [];

  for (int i = 0; i < n; i++) {
    char c = text[i];
    if (!convert.Latin1Codec().isValid(c)) continue;

    int shift = key.codeUnitAt(i % key.length);
    if (c >= 'a' && c <= 'z') {
      result.add(String.fromCharCode(((c - 'a'.codeUnitAt(0) + shift) % 26) + 'a'.codeUnitAt(0)));
    } else if (c >= 'A' && c <= 'Z') {
      result.add(String.fromCharCode(((c - 'A'.codeUnitAt(0) + shift) % 26) + 'A'.codeUnitAt(0)));
    } else {
      result.add(c.toString());
    }
  }

  return result.join();
}

