class ListBase {
  final int _capacity;
  late Object?[] _data;
  int _size = 0;

  ListBase(this._capacity) : _data = Object?[_capacity];

  void add(Object value) {
    if (_size == _capacity) {
      var newCapacity = _capacity * 2 + 1;
      var newData = Object?[newCapacity];
      for (int i = 0; i < _capacity; i++) {
        newData[i] = _data[i];
      }
      _data = newData!;
      _capacity = newCapacity;
    }
    _data[_size++] = value;
  }

  bool removeAt(int index, [Object? defaultValue]) {
    if (index >= 0 && index < _size) {
      _size--;
      for (var i = index; i < _size; i++) {
        _data[i] = _data[i + 1];
      }
      _data[_size] = defaultValue ?? null;
      return true;
    }
    return false;
  }

  bool get isEmpty => _size == 0;
}

