class UnionFind {
  final List<int> parent;
  final List<int> rank;

  UnionFind(int n) : parent = List.filled(n, -1), rank = List.filled(n, 0);

  int find(int x) {
    if (parent[x] < 0) return x;
    return parent[x] = find(parent[x]);
  }

  bool union(int a, int b) {
    int ra = find(a);
    int rb = find(b);
    if (ra == rb) return false;

    if (rank[ra] > rank[rb]) {
      parent[rb] = ra;
    } else if (rank[ra] < rank[rb]) {
      parent[ra] = rb;
    } else {
      parent[rb] = ra;
      rank[ra]++;
    }
    return true;
  }
}


