        for (Edge edge in graph[currentVertexMinDistance] ?? []) {
          double newDist = distanceMap[currentVertexMinDistance]! + edge.weight;

          if (newDist < distanceMap[edge.vertex]!) {
            distanceMap[edge.vertex] = newDist;

            if (!parentTemp.containsKey(edge.vertex)) {
              parentTemp[edge.vertex] = [currentVertexMinDistance];
            } else {
