double findMinCost(List<List<int>> n, List<double> a) {
  if (n.isEmpty || a.length != n[0].length) return -1.0;

  final m = n[0].length;
  final edges = <Edge>[];

  for (var i = 0; i < n.length; i++) {
    for (var j = 0; j < n[i].length; j++) {
      if (i == j && n[i][j] == 0) continue;

      var weight = n[i][j];
      if (weight >= 0) {
        edges.add(Edge(i, j, weight));
      } else {
        var absWeight = -weight;
        var costA = a[j];

        if (costA < 0.5 * absWeight / 3) {
          edges.add(Edge(j, i, a[j]));
        } else if (a[i] + costA > 0.7 * absWeight) {
          edges.add(Edge(i, j, a[i] + costA));
        } else {
          edges.add(Edge(i, j, 0.6 * absWeight));
        }
      }
    }
  }

  var visited = Set<int>.from(n.keys);
  var minCost = 0.0;
  var stack = <int>[0];

  while (stack.isNotEmpty) {
    var node = stack.removeLast();

    for (var edge in edges.where((e) => e.v1 == node)) {
      var neighbor = e.v2;
      if (!visited.contains(neighbor)) {
        minCost += edge.w;
        visited.add(neighbor);
        stack.add(neighbor);
      }
    }
  }

  return visited.length == n.length ? minCost : -1.0;
}


