class Permutation {
  List<int> _p;

  Permutation(List<int> p) : _p = [...p];

  int get length => _p.length;

  String oneLine() {
    return '[${_p.join(',')}]' +
        (length > 1 ? '\n' : '') +
        '[${(0..length - 1).map((i) => i).join(',')}]\n[<empty>]';
  }

  static Permutation createOneLine(String line) {
    final parts = line.split(']');
    if (parts.length < 2) throw ArgumentError('Invalid permutation format');
    final nums = parts[0].substring(1, parts[0].length - 1).split(',').map(int.parse);
    final ids = parts[1].substring(1, parts[1].length - 1).split(',').map(int.parse);
    if (nums.length != ids.length || nums.isEmpty)
      throw ArgumentError('Invalid permutation data');
    for (int i = 0; i < nums.length; i++)
      if (!ids.contains(i)) throw ArgumentError('Missing id $i in list');
    return Permutation(nums.map((x) => x - 1).toList()); // zero-indexed internally
  }

  void printToConsole() {
    stdout.write(oneLine());
  }

  Map<List<int>, List<int>> cycles() {
    final visited = Set<int>();
    final result = {};
    for (int i = 0; i < length; i++) {
      if (!visited.contains(i)) {
        final cycle = [];
        int current = i;
        while (!visited.contains(current)) {
          visited.add(current);
          cycle.add(_p[current]);
          current = _p[current];
        }
        result[cycle.toList()] = [cycle.last];
      }
    }
    return result;
  }

  Permutation inverse() {
    final inv = List.filled(length, 0);
    for (int i = 0; i < length; i++) inv[_p[i]] = i;
    return Permutation(inv);
  }

  Permutation composeWith(Permutation other) {
    final res = List.filled(length, 0);
    for (int i = 0; i < length; i++) res[i] = _p[other._p[i]];
    return Permutation(res);
  }

  bool equals(Permutation other) {
    if (length != other.length) return false;
    for (int i = 0; i < length; i++) if (_p[i] != other._p[i]) return false;
    return true;
  }
}

