  bool _hasCycle = false;

  Graph() : _adjacencyList = [] {}

  void addEdge(int u, int v, double w) {
    if (u < 0 || v < 0 || u >= _adjacencyList.length || v >= _adjacencyList.length) return;
    _adjacencyList[u] ??= [];
    _adjacencyList[v] ??= [];
    _adjacencyList[u]!.add(Edge(u, v, w));
    _adjacencyList[v]!.add(Edge(v, u, w));
  }

  void detectCycles(List<int> visited, List<bool> inStack) {
    for (int i = 0; i < _adjacencyList.length; i++) {
      if (!visited[i]) {
        visited[i] = true;
        inStack[i] = true;
        for (var edge in _adjacencyList[i]!) {
          if (!visited[edge.destination]) {
            detectCycles(visited, inStack);
          } else if (inStack[edge.destination]) {
            _hasCycle = true;
          }
        }
        inStack[i] = false;
      }
    }
  }

  double findMinWeightedPath(List<double> minDist, List<int> prevNode) {
    int u = -1;
    double minValue = double.infinity;
    for (int i = 0; i < _adjacencyList.length; i++) {
      if (_adjacencyList[i] == null) continue;
      if (minDist[i] != double.infinity &&
              minDist[i] < minValue &&
              !prevNode.contains(i)) {
        minValue = minDist[i];
        u = i;
      }
    }
    if (u == -1) return minValue;
    prevNode.add(u);
    for (var edge in _adjacencyList[u]!) {
      int v = edge.destination;
      double altValue = minDist[u] + edge.weight;
      if (altValue < minDist[v] && !prevNode.contains(v)) {
        minDist[v] = altValue;
        prevNode.removeWhere((x) => x == v);
        prevNode.insert(0, v);
      }
    }
    return minValue;
  }
}


